export function expBackoffJitter(attempt, baseMs) {
  return baseMs * 2 ** attempt;
}
export async function withRetry(run, attempts = 3) {
  let last;
  for (let attempt = 0; attempt < attempts; attempt += 1) {
    try {
      return await run();
    } catch (error) {
      last = error;
    }
  }
  throw last;
}
